type Product = { id: string; name: string; category: string; price: number; stock?: number; available?: boolean; discount?: number; unit?: string; image?: string; badge?: string };
type Category = { id: string; name: string; parentId?: string; sortOrder: number; active: boolean };
type OrderLine = { productId?: string; productName: string; quantity: number };
type Order = { id: string; status: string; total: number; pickupCode?: string; lines: OrderLine[]; customerName?: string; address?: string; slot?: string; distanceKm?: number; paymentMethod?: string };
type CartItem = { productId: string; productName: string; category: string; unitPrice: number; quantity: number; available: boolean };
type CartResponse = { items: CartItem[]; subtotal: number };
type Role = 'picker' | 'rider' | 'admin' | 'manager';
type Session = { accessToken: string; role: string; name: string; userId?: string };
type RiderGig = { id: string; title: string; time: string; duration: string; pay: number; orders: number; distance: string; store: string; area: string; status?: string };
type RiderEarnings = { today: number; week: number; month: number; orders: number; hours: number; payoutDay: string };
type RiderOffer = { title: string; detail: string; reward: number; color: string };
type RiderVehicle = { name: string; type: string; price: number; distance: string; available: boolean };
type PickerStore = { id?: string; name: string; area: string; distance: string; openOrders: number; status: string };
type PickerShift = { id: string; title: string; time: string; duration: string; pay: number; orders: number; store: string; status?: string };
type PickerEarnings = { today: number; week: number; month: number; orders: number; hours: number };

