const adminSample = adminData as { metrics: Record<string, number>; riders: Array<{ id: string; name: string; phone: string; vehicle: string; kyc: string; status: string; deliveries: number; rating: number }>; pickers: Array<{ id: string; name: string; store: string; status: string; orders: number; accuracy: number }>; inventory: Array<{ name: string; category: string; stock: number; reorderAt: number; store: string }>; complaints: Array<{ id: string; order: string; customer: string; type: string; status: string; time: string }>; notifications: string[] };
