    const Earnings = () => <><Header title="Earnings" share /><div className="ref-black-tabs"><button>Day</button><button className="active">Week</button><button>Month</button></div><div className="ref-date-card"><span>‹</span><b>19 Oct - 25 Oct</b><span>›</span><strong>₹358.96</strong></div><div className="ref-week-chart">₹61.31 <span>₹79.34</span>{[1,2,3,4,5,6,7].map(i => <i key={i} />)}</div><div className="ref-stat-row"><b>₹61.31<small>Earnings today</small></b><b>11<small>Orders</small></b><b>05:51 hrs<small>Hours</small></b></div><div className="ref-list-card"><p>Order earning <b>₹358.96</b></p><p>Incentive <b>₹0</b></p><p>Other earnings <b>₹0</b></p></div><Bottom /></>;
