         if (!root) return;
         const listeners: Array<[Element, EventListener]> = [];
         const bind = (element: Element | null, next: Screen) => { if (!element) return; const handler = () => setScreen(next); element.addEventListener('click', handler); listeners.push([element, handler]); };
         bind(root.querySelector('.ref-pocket-total'), 'pocket-balance');
